<script>
  (function() {
    // ---------- Maze generation (perfect, recursive backtracker) ----------
    function generateMaze(rows, cols, rng) {
      // rng: function returning float [0,1)
      const grid = Array.from({ length: rows }, () =>
        Array.from({ length: cols }, () => ({ n: true, s: true, e: true, w: true, visited: false }))
      );

      function shuffle(arr) {
        for (let i = arr.length - 1; i > 0; i--) {
          const j = Math.floor(rng() * (i + 1));
          [arr[i], arr[j]] = [arr[j], arr[i]];
        }
        return arr;
      }

      const stack = [];
      const startR = Math.floor(rng() * rows);
      const startC = Math.floor(rng() * cols);
      grid[startR][startC].visited = true;
      stack.push({ r: startR, c: startC });

      const directions = [
        { dr: -1, dc: 0, wall: 'n', opposite: 's' },
        { dr: 1, dc: 0, wall: 's', opposite: 'n' },
        { dr: 0, dc: 1, wall: 'e', opposite: 'w' },
        { dr: 0, dc: -1, wall: 'w', opposite: 'e' }
      ];

      while (stack.length) {
        const current = stack[stack.length - 1];
        const neighbors = [];
        for (const d of directions) {
          const nr = current.r + d.dr;
          const nc = current.c + d.dc;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !grid[nr][nc].visited) {
            neighbors.push({ nr, nc, dir: d });
          }
        }
        if (neighbors.length === 0) {
          stack.pop();
        } else {
          const chosen = neighbors[Math.floor(rng() * neighbors.length)];
          const { nr, nc, dir } = chosen;
          grid[current.r][current.c][dir.wall] = false;
          grid[nr][nc][dir.opposite] = false;
          grid[nr][nc].visited = true;
          stack.push({ r: nr, c: nc });
        }
      }
      return grid;
    }

    // ---------- Seeded random (mulberry32) ----------
    function mulberry32(a) {
      return function() {
        a |= 0; a = a + 0x6D2B79F5 | 0;
        let t = Math.imul(a ^ a >>> 15, 1 | a);
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
        return ((t ^ t >>> 14) >>> 0) / 4294967296;
      };
    }

    // ---------- BOT CLASS (pure exploration with Tremaux/DFS style) ----------
    class Bot {
      constructor(id, startR, startC, directionPreference) {
        this.id = id;
        this.start = { r: startR, c: startC };
        this.current = { r: startR, c: startC };
        this.path = [{ r: startR, c: startC }];
        this.deadEnds = [];         // cells marked as dead ends
        this.finishTick = null;
        // Exploration memory: per cell we store which directions have been explored from that cell.
        // Key: "r,c" -> Set of directions ('n','s','e','w') already attempted.
        this.explored = new Map();
        this._markExplored(startR, startC, null); // init cell memory
        // Direction preference order (will be used to decide next move when multiple options)
        this.dirOrder = directionPreference; // array of ['n','e','s','w'] shuffled per bot
        // For backtracking: stack of (r,c, directionTaken) to return
        this.moveStack = [];
      }

      _cellKey(r, c) { return `${r},${c}`; }

      _markExplored(r, c, direction) {
        const key = this._cellKey(r, c);
        if (!this.explored.has(key)) {
          this.explored.set(key, new Set());
        }
        if (direction) {
          this.explored.get(key).add(direction);
        }
      }

      _isExplored(r, c, dir) {
        const key = this._cellKey(r, c);
        return this.explored.has(key) && this.explored.get(key).has(dir);
      }

      // Returns the opposite direction
      _opposite(dir) {
        return { n: 's', s: 'n', e: 'w', w: 'e' }[dir];
      }

      // Decide next move based on local knowledge (no global BFS)
      // Returns { r, c, direction } or null if stuck (should not happen before exit)
      decideMove(mazeWalls, exitR, exitC, rows, cols) {
        if (this.finishTick !== null) return null; // already finished

        const { r, c } = this.current;
        // If at exit -> stop (finish handled externally)
        if (r === exitR && c === exitC) return null;

        const walls = mazeWalls(r, c);
        const possibleDirs = [];
        for (const dir of ['n', 'e', 's', 'w']) {
          if (!walls[dir]) {
            const nr = r + (dir === 'n' ? -1 : dir === 's' ? 1 : 0);
            const nc = c + (dir === 'e' ? 1 : dir === 'w' ? -1 : 0);
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            // Check if this passage has already been fully explored from this cell
            if (!this._isExplored(r, c, dir)) {
              possibleDirs.push({ dir, nr, nc });
            }
          }
        }

        // If no unexplored directions from current cell -> dead end (or backtrack situation)
        if (possibleDirs.length === 0) {
          // Mark current cell as dead end (if not already) and backtrack using moveStack
          const alreadyDead = this.deadEnds.some(d => d.r === r && d.c === c);
          if (!alreadyDead) {
            this.deadEnds.push({ r, c });
          }
          // Backtrack: pop last move from stack to return to previous cell
          if (this.moveStack.length === 0) {
            // Should not happen in a perfect maze with exit reachable; but safety
            return null;
          }
          const backtrack = this.moveStack.pop();
          // The direction to go back
          const backDir = this._opposite(backtrack.direction);
          // Mark the passage we took to come here as explored from the current cell
          this._markExplored(r, c, backDir);
          // Also mark from the target cell that we are moving back? We'll mark when we arrive.
          return { r: backtrack.r, c: backtrack.c, direction: backDir };
        }

        // Sort possible directions according to bot's personal preference order
        const prefOrder = this.dirOrder;
        possibleDirs.sort((a, b) => {
          const idxA = prefOrder.indexOf(a.dir);
          const idxB = prefOrder.indexOf(b.dir);
          return idxA - idxB;
        });

        // Pick the first unexplored direction
        const chosen = possibleDirs[0];
        // Mark this direction as explored from current cell
        this._markExplored(r, c, chosen.dir);
        // Push current move onto stack for potential backtracking
        this.moveStack.push({ r, c, direction: chosen.dir });
        return { r: chosen.nr, c: chosen.nc, direction: chosen.dir };
      }

      // Move to new cell, update path and mark arrived direction as explored from new cell
      moveTo(r, c, direction) {
        this.current = { r, c };
        this.path.push({ r, c });
        // Mark the entrance direction as explored in the new cell (so we don't go back immediately unless forced)
        const arrivedFrom = this._opposite(direction);
        this._markExplored(r, c, arrivedFrom);
      }

      // Force stop at exit
      setFinished(tick) {
        if (this.finishTick === null) {
          this.finishTick = tick;
          // clear movement stack, not needed anymore
        }
      }
    }

    // ---------- GAME STATE ----------
    const canvas = document.getElementById('mazeCanvas');
    const ctx = canvas.getContext('2d');

    const ROWS = 17;
    const COLS = 17;
    const BOT_COUNT = 24;
    const MAX_TICKS = 20000;

    // Colors for bots (distinct, pre-defined)
    const BOT_COLORS = [
      '#f4a261','#e76f51','#e9c46a','#2a9d8f','#287271','#9c89b8',
      '#f9844a','#43aa8b','#577590','#f94144','#f8961e','#f9c74f',
      '#90be6d','#4d908e','#277da1','#f3722c','#f9c74f','#b5838d',
      '#6d597a','#b56576','#eaac8b','#355070','#6d597a','#b56576'
    ];

    // Global state
    let mazeWalls = null;       // 2D array of wall objects
    let spawn = { r: 0, c: 0 };
    let exit = { r: ROWS-1, c: COLS-1 };
    let bots = [];
    let elapsed = 0;
    let timerFrozen = false;
    let completedCount = 0;
    let animationFrame = null;
    let currentSeed = 42;       // default seed

    // Deterministic RNG instance for current game
    let rng = mulberry32(currentSeed);

    // ---------- Helper: get walls for cell ----------
    function getWalls(r, c) {
      return mazeWalls[r][c];
    }

    // ---------- Maze generation with fixed spawn/exit placement using seed ----------
    function buildMaze(seed) {
      const localRng = mulberry32(seed);
      mazeWalls = generateMaze(ROWS, COLS, localRng);
      // Choose spawn and exit far apart (ensuring they are different)
      // Use deterministic but varied positions based on seed
      const seed2 = seed + 1000;
      const rng2 = mulberry32(seed2);
      const candidates = [];
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          candidates.push({ r, c });
        }
      }
      // shuffle candidates with rng2
      for (let i = candidates.length - 1; i > 0; i--) {
        const j = Math.floor(rng2() * (i + 1));
        [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
      }
      spawn = candidates[0];
      exit = candidates[1];
      // Ensure they are not identical (already)
    }

    // Create bots with different direction preferences
    function createBots(seed) {
      const botRng = mulberry32(seed + 5000);
      const baseOrders = ['n','e','s','w'];
      const botsArray = [];
      for (let i = 0; i < BOT_COUNT; i++) {
        // Shuffle direction order for each bot using botRng
        const order = [...baseOrders];
        for (let j = order.length - 1; j > 0; j--) {
          const k = Math.floor(botRng() * (j + 1));
          [order[j], order[k]] = [order[k], order[j]];
        }
        botsArray.push(new Bot(i, spawn.r, spawn.c, order));
      }
      return botsArray;
    }

    // Reset everything with optional seed
    function resetGame(seed = null) {
      if (seed !== undefined && seed !== null) {
        currentSeed = seed;
      } else {
        // generate new random seed if not provided
        currentSeed = Math.floor(Math.random() * 1000000);
      }
      rng = mulberry32(currentSeed);
      buildMaze(currentSeed);
      bots = createBots(currentSeed);
      elapsed = 0;
      timerFrozen = false;
      completedCount = 0;
      updateUI();
      drawMaze();
      if (animationFrame) cancelAnimationFrame(animationFrame);
      animationFrame = null;
    }

    // Advance simulation by n ticks (synchronous, deterministic)
    function tick(n = 1) {
      if (n <= 0) return;
      for (let step = 0; step < n; step++) {
        if (timerFrozen) break; // no more ticks after last arrival
        elapsed++;
        let anyActive = false;
        for (const bot of bots) {
          if (bot.finishTick !== null) continue;
          anyActive = true;
          // Check if currently at exit (should have been set, but safety)
          if (bot.current.r === exit.r && bot.current.c === exit.c) {
            bot.setFinished(elapsed);
            completedCount++;
            continue;
          }
          const move = bot.decideMove(getWalls, exit.r, exit.c, ROWS, COLS);
          if (move) {
            bot.moveTo(move.r, move.c, move.direction);
            // After moving, check if arrived at exit
            if (bot.current.r === exit.r && bot.current.c === exit.c) {
              bot.setFinished(elapsed);
              completedCount++;
            }
          } else {
            // No move decided but not at exit? could be stuck (should not happen)
            // If bot is at exit but not finished, mark it now.
            if (bot.current.r === exit.r && bot.current.c === exit.c) {
              bot.setFinished(elapsed);
              completedCount++;
            }
          }
        }
        // Update completed count from bots
        completedCount = bots.filter(b => b.finishTick !== null).length;
        updateUI();

        if (!anyActive || completedCount === BOT_COUNT) {
          timerFrozen = true;
          break;
        }
        if (elapsed >= MAX_TICKS) {
          timerFrozen = true;
          break;
        }
      }
      drawMaze();
    }

    // UI updates
    function updateUI() {
      document.getElementById('timer').textContent = elapsed;
      document.getElementById('completed').textContent = completedCount;
    }

    // ---------- RENDERING (smooth interpolation) ----------
    let lastDrawTime = 0;
    const CELL_SIZE = 30;       // pixels
    const PADDING = 10;
    const WALL_WIDTH = 2.5;

    function drawMaze(timestamp = 0) {
      // We'll use requestAnimationFrame for smooth continuous redraw, but we also call directly.
      if (!mazeWalls) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const offsetX = PADDING;
      const offsetY = PADDING;
      const totalWidth = COLS * CELL_SIZE;
      const totalHeight = ROWS * CELL_SIZE;

      // Draw background
      ctx.fillStyle = '#0b1117';
      ctx.fillRect(offsetX, offsetY, totalWidth, totalHeight);

      // Draw walls
      ctx.strokeStyle = '#5e6b7c';
      ctx.lineWidth = WALL_WIDTH;
      ctx.lineCap = 'round';

      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = offsetX + c * CELL_SIZE;
          const y = offsetY + r * CELL_SIZE;
          const w = mazeWalls[r][c];
          if (w.n) {
            ctx.beginPath();
            ctx.moveTo(x, y);
            ctx.lineTo(x + CELL_SIZE, y);
            ctx.stroke();
          }
          if (w.s) {
            ctx.beginPath();
            ctx.moveTo(x, y + CELL_SIZE);
            ctx.lineTo(x + CELL_SIZE, y + CELL_SIZE);
            ctx.stroke();
          }
          if (w.w) {
            ctx.beginPath();
            ctx.moveTo(x, y);
            ctx.lineTo(x, y + CELL_SIZE);
            ctx.stroke();
          }
          if (w.e) {
            ctx.beginPath();
            ctx.moveTo(x + CELL_SIZE, y);
            ctx.lineTo(x + CELL_SIZE, y + CELL_SIZE);
            ctx.stroke();
          }
        }
      }

      // Draw spawn and exit markers
      const sx = offsetX + spawn.c * CELL_SIZE + CELL_SIZE/2;
      const sy = offsetY + spawn.r * CELL_SIZE + CELL_SIZE/2;
      ctx.beginPath();
      ctx.arc(sx, sy, CELL_SIZE*0.3, 0, 2*Math.PI);
      ctx.fillStyle = '#cad3f5';
      ctx.globalAlpha = 0.5;
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1.8;
      ctx.stroke();

      const ex = offsetX + exit.c * CELL_SIZE + CELL_SIZE/2;
      const ey = offsetY + exit.r * CELL_SIZE + CELL_SIZE/2;
      ctx.beginPath();
      ctx.arc(ex, ey, CELL_SIZE*0.3, 0, 2*Math.PI);
      ctx.fillStyle = '#a6da95';
      ctx.globalAlpha = 0.6;
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.strokeStyle = '#f0fff0';
      ctx.stroke();

      // Draw bots with smooth interpolation between path cells.
      // For each bot, we compute current interpolated position based on elapsed ticks and path.
      if (bots.length > 0) {
        // We need a time fraction for smooth movement. Since tick() is called synchronously,
        // we can interpolate between last path cell and current cell using a simple animation progress.
        // For a moving bot, we'll animate between previous position and current position.
        // We'll use a global animation progress that loops.
        const now = performance.now();
        const animProgress = (now % 1000) / 1000; // 0..1 every second, but we want per tick interpolation.
        // Better: use a fixed interpolation based on drawing time relative to last tick.
        // Since ticks are discrete, we show bots at their current cell but with a slight offset
        // towards next? Actually bots only occupy cells at integer ticks. To make smooth,
        // we interpolate between the last two path entries: path[path.length-2] -> path[path.length-1].
        // If bot just moved, we smoothly transition.
        for (let i = 0; i < bots.length; i++) {
          const bot = bots[i];
          if (bot.finishTick !== null && bot.path.length > 0) {
            // bot stopped at exit, draw at exit cell
            const pos = bot.path[bot.path.length-1];
            drawBot(pos.r, pos.c, BOT_COLORS[i % BOT_COLORS.length], offsetX, offsetY);
            continue;
          }
          const pathLen = bot.path.length;
          if (pathLen < 2) {
            if (pathLen === 1) drawBot(bot.path[0].r, bot.path[0].c, BOT_COLORS[i % BOT_COLORS.length], offsetX, offsetY);
            continue;
          }
          const prev = bot.path[pathLen-2];
          const curr = bot.path[pathLen-1];
          // Interpolation factor: smooth continuous motion. We'll use a time-based factor.
          // Since we want smooth movement between cells without teleporting, we use a shared
          // animation cycle. But the bot may have moved multiple ticks ago. We'll use a constant
          // animation progress that loops independent of ticks, giving a subtle floating feel.
          // For a game-like smooth move, we interpolate from prev to curr.
          const t = 0.5 + 0.5 * Math.sin(now * 0.008 + i); // gentle oscillation, but better:
          // We want bots to actually glide from previous to current. Use a linear factor based on time since last tick?
          // Simple: use a fixed factor of 0.7 (closer to current) but with slight variation per bot.
          const factor = 0.7;
          const interpR = prev.r + (curr.r - prev.r) * factor;
          const interpC = prev.c + (curr.c - prev.c) * factor;
          drawBot(interpR, interpC, BOT_COLORS[i % BOT_COLORS.length], offsetX, offsetY);
        }
      }

      // Request next frame for continuous smooth animation
      if (!animationFrame) {
        animationFrame = requestAnimationFrame(drawMaze);
      }
    }

    function drawBot(r, c, color, offX, offY) {
      const cx = offX + c * CELL_SIZE + CELL_SIZE/2;
      const cy = offY + r * CELL_SIZE + CELL_SIZE/2;
      ctx.beginPath();
      ctx.arc(cx, cy, CELL_SIZE*0.32, 0, 2*Math.PI);
      ctx.fillStyle = color;
      ctx.shadowColor = '#00000080';
      ctx.shadowBlur = 6;
      ctx.fill();
      ctx.shadowColor = 'transparent';
      ctx.shadowBlur = 0;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1.4;
      ctx.stroke();
    }

    // Override drawMaze to loop animation
    function startAnimationLoop() {
      if (animationFrame) cancelAnimationFrame(animationFrame);
      function loop(ts) {
        drawMaze(ts);
        animationFrame = requestAnimationFrame(loop);
      }
      animationFrame = requestAnimationFrame(loop);
    }

    // ---------- Expose window.game API ----------
    window.game = {
      tick(n) {
        if (typeof n !== 'number' || n < 1) n = 1;
        // For deterministic: tick(1) n times equals tick(n)
        for (let i = 0; i < n; i++) {
          if (timerFrozen) break;
          this._singleTick();
        }
        drawMaze();
      },
      _singleTick() {
        if (timerFrozen) return;
        elapsed++;
        let anyActive = false;
        for (const bot of bots) {
          if (bot.finishTick !== null) continue;
          anyActive = true;
          if (bot.current.r === exit.r && bot.current.c === exit.c) {
            bot.setFinished(elapsed);
            completedCount++;
            continue;
          }
          const move = bot.decideMove(getWalls, exit.r, exit.c, ROWS, COLS);
          if (move) {
            bot.moveTo(move.r, move.c, move.direction);
            if (bot.current.r === exit.r && bot.current.c === exit.c) {
              bot.setFinished(elapsed);
              completedCount++;
            }
          } else {
            if (bot.current.r === exit.r && bot.current.c === exit.c && bot.finishTick === null) {
              bot.setFinished(elapsed);
              completedCount++;
            }
          }
        }
        completedCount = bots.filter(b => b.finishTick !== null).length;
        updateUI();
        if (!anyActive || completedCount === BOT_COUNT || elapsed >= MAX_TICKS) {
          timerFrozen = true;
        }
      },
      reset(seed) {
        if (animationFrame) cancelAnimationFrame(animationFrame);
        animationFrame = null;
        resetGame(seed);
        startAnimationLoop();
      },
      get elapsed() {
        return elapsed;
      },
      get size() {
        return { rows: ROWS, cols: COLS };
      },
      get spawn() {
        return { ...spawn };
      },
      get exit() {
        return { ...exit };
      },
      walls(r, c) {
        if (!mazeWalls || r < 0 || r >= ROWS || c < 0 || c >= COLS) return null;
        const w = mazeWalls[r][c];
        return { n: w.n, e: w.e, s: w.s, w: w.w };
      },
      get bots() {
        return bots.map(b => ({
          path: b.path.map(p => ({ r: p.r, c: p.c })),
          deadEnds: b.deadEnds.map(d => ({ r: d.r, c: d.c })),
          finishTick: b.finishTick
        }));
      }
    };

    // Initialise
    resetGame(currentSeed);
    startAnimationLoop();

